def is_latin_square(subset):
    n = len(subset)
    for i in range(n):
        seen = set()
        for j in range(n):
            if subset[i][j] in seen:
                return False
            seen.add(subset[i][j])
    return True

def find_good_subset(arrays, n):
    from itertools import combinations

    for subset in combinations(range(2 * n), n):
        subset = [arrays[i] for i in subset]
        if is_latin_square(subset):
            return subset
    return None

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    t = int(data[0])
    index = 1
    results = []

    for _ in range(t):
        n = int(data[index])
        index += 1
        arrays = []
        for _ in range(2 * n):
            array = list(map(int, data[index:index + n]))
            arrays.append(array)
            index += n

        good_subset = find_good_subset(arrays, n)
        if good_subset:
            indices = [i + 1 for i in range(n)]
            results.append(f"{1}\n{' '.join(map(str, indices))}")
        else:
            results.append(f"{0}\n{' '.join(map(str, indices))}")

    print('\n'.join(results))

if __name__ == "__main__":
    main()
